  @{ n=12; t="Leptospirosis"; c="A27.9"; def="Zoonosis espiroquetal transmitida por orina de roedores y aguas contaminadas, endémica en Loreto, Madre de Dios y costa rural."; sym=@("Fiebre súbita y cefalea intensa", "Sufusión conjuntival marcada (patognomónica)", "Mialgias intensas en pantorrillas y región lumbar", "Ictericia y coluria (Síndrome de Weil)"); rf=@("Oliguria o anuria (Fallo renal agudo)", "Hemoptisis (Hemorragia pulmonar leptospirósica)", "Ictericia marcada con diátesis hemorrágica"); crit="Criterios epidemiológicos de exposición a aguas estancadas/roedores + confirmación por microaglutinación (MAT) o ELISA IgM."; labs=@("Prueba de Microaglutinación (MAT) en el INS", "ELISA IgM para Leptospira", "Creatinina y urea sérica (falla renal típicamente hipopotasémica en fase inicial)", "Bilirrubinas a predominio directo y CPK muy elevada"); img=@("Radiografía de tórax (infiltrados alveolares bilaterales por hemorragia alveolar)"); diff=@("Dengue grave", "Fiebre amarilla", "Malaria grave", "Hepatitis viral aguda"); drugs=@(@{ drug="Doxiciclina"; dose="100 mg cada 12 horas por 7 días"; route="VO"; freq="c/12h"; notes="Para casos leves a moderados según guía MINSA" }, @{ drug="Penicilina G Sódica"; dose="1.5 millones UI cada 6 horas EV por 7 días"; route="EV"; freq="c/6h"; notes="Para formas severas o Síndrome de Weil (alternativa Ceftriaxona 1-2g c/24h)" }); nursing=@("Control estricto de diuresis horaria con bolsa colectora (vigilar oliguria temprana)", "Monitoreo de función respiratoria y detección precoz de esputo hemoptoico", "Manejo cauteloso de líquidos para evitar sobrecarga en presencia de fallo renal", "Educación en el uso de botas de jebe y control de roedores en el hogar") },
