  @{ n=63; t="Tricocefalosis"; c="B79"; cat="Infecciosas y Zoonóticas"; def="Infección por Trichuris trichiura con fijación en ciego y colon que en niños causa diarrea crónica disentérica y prolapso rectal."; drugs="Mebendazol 100 mg c/12h por 3 días o Albendazol 400 mg/d x 3 días" },
