  @{ n=70; t="Tricomoniasis urogenital"; c="A59.0"; cat="Infecciosas y Zoonóticas"; def="Infección protozoaria por Trichomonas vaginalis con leucorrea amarillo-verdosa espumosa fétida, prurito y 'cérvix en fresa'."; drugs="Metronidazol 2 g VO dosis única o 500 mg c/12h por 7 días (tratar a la pareja)" },
