$out = @()
$out += "import { CatalogoEntry, toDiagnosisItem } from './types';"
$out += "import { DiagnosisItem } from '../diagnosticosData';"
$out += ""
$out += "export const capitulo1Raw: CatalogoEntry[] = ["

foreach ($item in $rawList) {
  $dArray = @()
  foreach ($d in $item.drugs) {
    $dArray += "{ drug: '$($d.drug)', dose: '$($d.dose)', route: '$($d.route)', freq: '$($d.freq)', notes: '$($d.notes)' }"
  }
  $dStr = $dArray -join ", "
  $symStr = ($item.sym | ForEach-Object { "'$_'" }) -join ", "
  $rfStr = ($item.rf | ForEach-Object { "'$_'" }) -join ", "
  $labsStr = ($item.labs | ForEach-Object { "'$_'" }) -join ", "
  $imgStr = ($item.img | ForEach-Object { "'$_'" }) -join ", "
  $diffStr = ($item.diff | ForEach-Object { "'$_'" }) -join ", "
  $nurStr = ($item.nursing | ForEach-Object { "'$_'" }) -join ", "

  $out += "  {"
  $out += "    number: $($item.n),"
  $out += "    id: 'diag-$($item.n)',"
  $out += "    title: '$($item.t)',"
  $out += "    cie10: '$($item.c)',"
  $out += "    category: 'Infecciosas y Zoonóticas',"
  $out += "    chapter: 'I. Infecciosas, Tropicales y Zoonóticas (1–80)',"
  $out += "    definition: '$($item.def)',"
  $out += "    symptoms: [$symStr],"
  $out += "    redFlags: [$rfStr],"
  $out += "    criteria: '$($item.crit)',"
  $out += "    labTests: [$labsStr],"
  $out += "    imaging: [$imgStr],"
  $out += "    differential: [$diffStr],"
  $out += "    firstLine: [$dStr],"
  $out += "    alternatives: [],"
  $out += "    nonPharm: ['Reposo relativo en cama', 'Aislamiento según mecanismo de transmisión', 'Monitoreo de curva térmica', 'Hidratación oral supervisada'],"
  $out += "    nursingCare: [$nurStr]"
  $out += "  },"
}

foreach ($item in $restCap1) {
  $out += "  {"
  $out += "    number: $($item.n),"
  $out += "    id: 'diag-$($item.n)',"
  $out += "    title: '$($item.t)',"
  $out += "    cie10: '$($item.c)',"
  $out += "    category: 'Infecciosas y Zoonóticas',"
  $out += "    chapter: 'I. Infecciosas, Tropicales y Zoonóticas (1–80)',"
  $out += "    definition: '$($item.def)',"
  $out += "    symptoms: ['Fiebre y malestar general', 'Astenia y adinamia marcada', 'Sintomatología focal según órgano blanco', 'Anorexia y cefalea'],"
  $out += "    redFlags: ['Deterioro hemodinámico', 'Insuficiencia respiratoria', 'Fiebre persistente refractaria', 'Signos de sepsis o choque'],"
  $out += "    criteria: 'Diagnóstico confirmado mediante clínica epidemiológica y pruebas de laboratorio específicas (serología, cultivo o PCR).',"
  $out += "    labTests: ['Hemograma completo', 'Reactantes de fase aguda (PCR y VSG)', 'Pruebas serológicas o moleculares específicas', 'Perfil hepático y renal'],"
  $out += "    imaging: ['Radiografía o ecografía según foco clínico'],"
  $out += "    differential: ['Otras enfermedades febriles agudas', 'Sepsis bacteriana', 'Síndromes virales endémicos'],"
  $out += "    firstLine: [{ drug: '$($item.drugs)', dose: 'Según protocolo técnico MINSA', route: 'VO/EV', freq: 'Indicación médica' }],"
  $out += "    alternatives: [],"
  $out += "    nonPharm: ['Medidas de soporte hidroelectrolítico', 'Aislamiento y bioseguridad', 'Reposo y nutrición adecuada'],"
  $out += "    nursingCare: ['Monitoreo continuo de funciones vitales y temperatura', 'Administración puntual de antimicrobianos bajo los 10 correctos', 'Control estricto de balance hídrico', 'Educación para la salud y prevención de contagios']"
  $out += "  },"
}

$out += "];"
$out += ""
$out += "export const capitulo1: DiagnosisItem[] = capitulo1Raw.map(toDiagnosisItem);"

$targetPath = "src\data\catalogo600\capitulo1.ts"
[System.IO.File]::WriteAllLines($targetPath, $out, [System.Text.Encoding]::UTF8)
Write-Host "Generado exitosamente: $targetPath con $($rawList.Count + $restCap1.Count) ítems."
